package hydoassert_test

// The shared cases (sdk/cases, generated by the Rust SDK's tests; sdk/rust/README.md, "The
// shared cases"): for every case and run, this test starts itself as a child process (fresh
// SDK state), the child makes the case's calls through hydoassert and hydohist, and the
// parent compares what the sink received and what the calls returned with the case's files.
//
//	go test ./...                         (in sdk/go)
//	GOTOOLCHAIN=go1.26.5 go test ./...    (the Go of the guest images: also the invalid-UTF-8 cases)
//
// Go 1.27 writes an invalid UTF-8 byte as a raw U+FFFD instead of the escape \ufffd that the
// guest images' Go 1.26.5 writes, so with Go 1.27 or later the cases that need "invalid_utf8"
// are skipped (and reported). The Go SDK has no emit_line, so "emit_line" cases are skipped.

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/kakoc/hydo/sdk/go/hydoassert"
	"github.com/kakoc/hydo/sdk/go/hydohist"
)

type caseRun struct {
	Name        string  `json:"name"`
	Out         string  `json:"out"`
	HistOut     string  `json:"hist_out"`
	BuggifyEnv  *string `json:"buggify_env"`
	BuggifyFile *string `json:"buggify_file"`
	Output      string  `json:"output"`
	Returns     string  `json:"returns"`
}

type caseFile struct {
	About string                   `json:"about"`
	Needs []string                 `json:"needs"`
	Steps []map[string]interface{} `json:"steps"`
	Runs  []caseRun                `json:"runs"`
}

const casesDir = "../../cases"
const pre = "PRE existing line\n"

// goMinor is the minor version of the Go that built this test (27 for go1.27.3), or 0.
func goMinor() int {
	m := regexp.MustCompile(`^go1\.(\d+)`).FindStringSubmatch(runtime.Version())
	if m == nil {
		return 0
	}
	n, _ := strconv.Atoi(m[1])
	return n
}

// skipReason says why this SDK cannot run a case, "" if it can.
func skipReason(needs []string) (string, error) {
	for _, n := range needs {
		switch n {
		case "f32", "bytes", "raw_hist":
		case "emit_line":
			return "the Go SDK has no emit_line", nil
		case "steer":
			return "the Go SDK has no steered values yet (the Rust SDK has them first, Milestone 209)", nil
		case "invalid_utf8":
			if goMinor() >= 27 {
				return runtime.Version() + " writes invalid UTF-8 as a raw U+FFFD; the cases hold Go 1.26's \\ufffd (run with GOTOOLCHAIN=go1.26.5)", nil
			}
		default:
			return "", fmt.Errorf("unknown need %q: update this test", n)
		}
	}
	return "", nil
}

func TestCases(t *testing.T) {
	if os.Getenv("HYDO_CASE_FILE") != "" {
		t.Skip("child")
	}
	files, err := filepath.Glob(filepath.Join(casesDir, "*", "*.json"))
	if err != nil || len(files) == 0 {
		t.Fatalf("no cases in %s (%v)", casesDir, err)
	}
	sort.Strings(files)
	ran, skipped := 0, map[string]int{}
	for _, f := range files {
		var c caseFile
		b, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(b, &c); err != nil {
			t.Fatalf("%s: %v", f, err)
		}
		id := strings.TrimSuffix(strings.TrimPrefix(filepath.ToSlash(f), casesDir+"/"), ".json")
		why, err := skipReason(c.Needs)
		if err != nil {
			t.Fatalf("%s: %v", id, err)
		}
		if why != "" {
			skipped[why]++
			continue
		}
		for _, r := range c.Runs {
			name := id
			if r.Name != "" {
				name += "/" + r.Name
			}
			t.Run(name, func(t *testing.T) { runCase(t, f, filepath.Dir(f), r) })
			ran++
		}
	}
	for why, n := range skipped {
		t.Logf("skipped %d cases: %s", n, why)
	}
	t.Logf("%d runs of %d case files", ran, len(files))
}

func runCase(t *testing.T, file, dir string, r caseRun) {
	tmp := t.TempDir()
	env := []string{}
	for _, e := range os.Environ() {
		if !strings.HasPrefix(e, "HYDO_") {
			env = append(env, e)
		}
	}
	abs, _ := filepath.Abs(file)
	env = append(env, "HYDO_CASE_FILE="+abs, "HYDO_CASE_RETURNS="+filepath.Join(tmp, "returns"))
	if r.BuggifyEnv != nil {
		env = append(env, "HYDO_BUGGIFY="+*r.BuggifyEnv)
	}
	if r.BuggifyFile != nil {
		os.WriteFile(filepath.Join(tmp, "buggify"), []byte(*r.BuggifyFile), 0644)
		env = append(env, "HYDO_BUGGIFY_FILE="+filepath.Join(tmp, "buggify"))
	} else {
		env = append(env, "HYDO_BUGGIFY_FILE="+filepath.Join(tmp, "no-buggify"))
	}
	console, hist := filepath.Join(tmp, "console"), filepath.Join(tmp, "hist")
	switch r.Out {
	case "file", "append":
		c := ""
		if r.Out == "append" {
			c = pre
		}
		os.WriteFile(console, []byte(c), 0644)
		env = append(env, "HYDO_ASSERT_OUT="+console)
	case "stderr", "off":
		env = append(env, "HYDO_ASSERT_OUT="+r.Out)
	case "missing":
		env = append(env, "HYDO_ASSERT_OUT="+filepath.Join(tmp, "missing"))
	default:
		t.Fatalf("out %q", r.Out)
	}
	switch r.HistOut {
	case "file", "append":
		c := ""
		if r.HistOut == "append" {
			c = pre
		}
		os.WriteFile(hist, []byte(c), 0644)
		env = append(env, "HYDO_HIST_OUT="+hist)
	case "create":
		env = append(env, "HYDO_HIST_OUT="+hist)
	case "stderr", "off":
		env = append(env, "HYDO_HIST_OUT="+r.HistOut)
	case "fallback":
		env = append(env, "HYDO_HIST_OUT="+filepath.Join(tmp, "no-such-dir", "hist"))
	default:
		t.Fatalf("hist_out %q", r.HistOut)
	}
	cmd := exec.Command(os.Args[0], "-test.run=^TestCaseChild$")
	cmd.Env = env
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("child: %v\n%s%s", err, stdout.String(), stderr.String())
	}
	toStderr := r.Out == "stderr" || r.Out == "missing" || r.HistOut == "stderr" || r.HistOut == "fallback"
	if !toStderr && stderr.Len() > 0 {
		t.Fatalf("wrote to stderr: %q", stderr.String())
	}
	var got []byte
	switch {
	case toStderr:
		got = stderr.Bytes()
	case r.Out != "off":
		got, _ = os.ReadFile(console)
	case r.HistOut != "off":
		var err error
		if got, err = os.ReadFile(hist); err != nil {
			t.Fatalf("history file: %v", err)
		}
	}
	got, err := maskTimes(got)
	if err != nil {
		t.Fatal(err)
	}
	want, err := os.ReadFile(filepath.Join(dir, r.Output))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Errorf("output differs from %s, %s", r.Output, firstDifference(want, got))
	}
	ret, _ := os.ReadFile(filepath.Join(tmp, "returns"))
	if string(ret) != r.Returns {
		t.Errorf("returns differ:\n    case: %s\n    go:   %s", r.Returns, ret)
	}
}

// maskTimes replaces the time field of each HYDO-HIST record with "*"; the times must be
// decimal integers that never decrease.
func maskTimes(b []byte) ([]byte, error) {
	var out [][]byte
	prev := int64(-1)
	for _, l := range bytes.SplitAfter(b, []byte("\n")) {
		if bytes.HasPrefix(l, []byte("HYDO-HIST ")) {
			f := bytes.SplitN(l, []byte(" "), 6)
			if len(f) < 6 {
				return nil, fmt.Errorf("short record %q", l)
			}
			n, err := strconv.ParseInt(string(f[4]), 10, 64)
			if err != nil || n < prev {
				return nil, fmt.Errorf("time %q is not a non-decreasing decimal integer", f[4])
			}
			prev = n
			f[4] = []byte("*")
			l = bytes.Join(f, []byte(" "))
		}
		out = append(out, l)
	}
	return bytes.Join(out, nil), nil
}

func firstDifference(want, got []byte) string {
	w, g := bytes.Split(want, []byte("\n")), bytes.Split(got, []byte("\n"))
	for i := 0; i < len(w) || i < len(g); i++ {
		var a, b []byte
		if i < len(w) {
			a = w[i]
		}
		if i < len(g) {
			b = g[i]
		}
		if !bytes.Equal(a, b) || (i < len(w)) != (i < len(g)) {
			return fmt.Sprintf("line %d:\n    case: %q\n    go:   %q", i+1, a, b)
		}
	}
	return "(equal)"
}

// ---- the child ----

func TestCaseChild(t *testing.T) {
	f := os.Getenv("HYDO_CASE_FILE")
	if f == "" {
		t.Skip("run by TestCases")
	}
	var c caseFile
	b, err := os.ReadFile(f)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(b, &c); err != nil {
		t.Fatal(err)
	}
	ret := execute(t, c.Steps)
	if err := os.WriteFile(os.Getenv("HYDO_CASE_RETURNS"), []byte(ret), 0644); err != nil {
		t.Fatal(err)
	}
}

// str is a case string: plain text, or {"raw": [text or byte, ...]}.
func str(x interface{}) string {
	switch v := x.(type) {
	case string:
		return v
	case map[string]interface{}:
		var b []byte
		for _, p := range v["raw"].([]interface{}) {
			switch q := p.(type) {
			case string:
				b = append(b, q...)
			case float64:
				b = append(b, byte(q))
			}
		}
		return string(b)
	}
	panic(fmt.Sprintf("not a string: %v", x))
}

func float(s string, bits int) float64 {
	switch s {
	case "NaN":
		return math.NaN()
	case "+Inf":
		return math.Inf(1)
	case "-Inf":
		return math.Inf(-1)
	}
	f, err := strconv.ParseFloat(s, bits)
	if err != nil {
		panic(err)
	}
	return f
}

func integer(x interface{}) int64 {
	n, err := strconv.ParseInt(x.(map[string]interface{})["int"].(string), 10, 64)
	if err != nil {
		panic(err)
	}
	return n
}

// val is a case value as the Go value of its type.
func val(x interface{}) interface{} {
	switch v := x.(type) {
	case nil, bool, string:
		return v
	case []interface{}:
		l := make([]interface{}, len(v))
		for i, e := range v {
			l[i] = val(e)
		}
		return l
	case map[string]interface{}:
		for tag, y := range v {
			switch tag {
			case "int":
				return integer(v)
			case "uint":
				n, err := strconv.ParseUint(y.(string), 10, 64)
				if err != nil {
					panic(err)
				}
				return n
			case "f64":
				return float(y.(string), 64)
			case "f32":
				return float32(float(y.(string), 32))
			case "raw":
				return str(v)
			case "bytes":
				b, err := hex.DecodeString(y.(string))
				if err != nil {
					panic(err)
				}
				return b
			case "map":
				m := map[string]interface{}{}
				for _, kv := range y.([]interface{}) {
					p := kv.([]interface{})
					m[str(p[0])] = val(p[1])
				}
				return m
			}
		}
	}
	panic(fmt.Sprintf("not a value: %v", x))
}

func details(s map[string]interface{}) hydoassert.D {
	d, ok := s["details"]
	if !ok {
		return nil
	}
	return hydoassert.D(val(d).(map[string]interface{}))
}

// arg is a history record argument: a token, or one of the recorder's helpers.
func arg(x interface{}) string {
	m, ok := x.(map[string]interface{})
	if !ok {
		return str(x)
	}
	strs := func(l interface{}) []string {
		var s []string
		for _, e := range l.([]interface{}) {
			s = append(s, str(e))
		}
		return s
	}
	for tag, y := range m {
		switch tag {
		case "raw":
			return str(m)
		case "enc":
			return hydohist.Enc(str(y))
		case "ver":
			p := y.([]interface{})
			n, err := strconv.ParseInt(p[1].(string), 10, 64)
			if err != nil {
				panic(err)
			}
			return hydohist.Ver(str(p[0]), n)
		case "value_or_nil":
			if y == nil {
				return hydohist.ValOrNil("", false)
			}
			return hydohist.ValOrNil(str(y), true)
		case "list":
			return hydohist.List(strs(y)...)
		case "append_mop":
			p := y.([]interface{})
			return hydohist.Append(str(p[0]), str(p[1]))
		case "read_mop":
			return hydohist.Read(str(y))
		case "read_result_mop":
			p := y.([]interface{})
			return hydohist.ReadResult(str(p[0]), strs(p[1])...)
		case "nil":
			return hydohist.Nil
		}
	}
	panic(fmt.Sprintf("not an argument: %v", x))
}

func args(s map[string]interface{}) []string {
	var a []string
	for _, x := range s["args"].([]interface{}) {
		a = append(a, arg(x))
	}
	return a
}

func execute(t *testing.T, steps []map[string]interface{}) string {
	var (
		objs    []interface{}
		watches []*hydoassert.Watch
		hists   []*hydohist.History
		ops     []*hydohist.Op
		ret     strings.Builder
	)
	push := func(b bool) {
		if b {
			ret.WriteByte('1')
		} else {
			ret.WriteByte('0')
		}
	}
	ix := func(s map[string]interface{}, k string) int { return int(s[k].(float64)) }
	asr := func(s map[string]interface{}) *hydoassert.Assertion { return objs[ix(s, "a")].(*hydoassert.Assertion) }
	for _, s := range steps {
		switch s["do"] {
		case "always":
			objs = append(objs, hydoassert.Always(str(s["id"]), str(s["msg"])))
		case "always_or_unreachable":
			objs = append(objs, hydoassert.AlwaysOrUnreachable(str(s["id"]), str(s["msg"])))
		case "sometimes":
			objs = append(objs, hydoassert.Sometimes(str(s["id"]), str(s["msg"])))
		case "reachable":
			objs = append(objs, hydoassert.Reachable(str(s["id"]), str(s["msg"])))
		case "unreachable":
			objs = append(objs, hydoassert.Unreachable(str(s["id"]), str(s["msg"])))
		case "eventually":
			objs = append(objs, hydoassert.Eventually(str(s["id"]), str(s["msg"]), time.Duration(ix(s, "within_ms"))*time.Millisecond))
		case "buggify":
			objs = append(objs, hydoassert.Buggify(str(s["id"]), str(s["msg"])))
		case "check":
			push(asr(s).Check(s["cond"].(bool), details(s)))
		case "hit":
			asr(s).Hit(details(s))
		case "cmp":
			push(asr(s).Cmp(integer(s["left"]), s["op"].(string), integer(s["right"]), details(s)))
		case "begin":
			watches = append(watches, objs[ix(s, "a")].(*hydoassert.Liveness).Begin())
		case "done":
			push(watches[ix(s, "w")].Done(details(s)))
		case "expire":
			watches[ix(s, "w")].Expire(details(s))
		case "await": // "async" too: Go has one Await
			push(objs[ix(s, "a")].(*hydoassert.Liveness).Await(func() bool { return true }, time.Millisecond, details(s)))
		case "fire":
			push(objs[ix(s, "a")].(*hydoassert.Point).Fire(details(s)))
		case "catalog":
			hydoassert.Catalog()
		case "setup_complete":
			hydoassert.SetupComplete()
		case "history":
			hists = append(hists, hydohist.New(s["name"].(string)))
		case "invoke":
			ops = append(ops, hists[ix(s, "h")].Invoke(int(integer(s["proc"])), s["f"].(string), args(s)...))
		case "ok":
			ops[ix(s, "o")].Ok(args(s)...)
		case "ok_same":
			ops[ix(s, "o")].Ok()
		case "fail":
			ops[ix(s, "o")].Fail()
		case "info":
			ops[ix(s, "o")].Info()
		case "record":
			hists[ix(s, "h")].Record(int(integer(s["proc"])), s["type"].(string), s["f"].(string), args(s)...)
		default:
			t.Fatalf("unknown step %v: update this test", s["do"])
		}
	}
	return ret.String()
}
